def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
    opp_c = n - opp_d

    start = n - 5
    if start < 0:
        start = 0
    recent_len = n - start
    recent_opp_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_opp_coop = recent_opp_c / float(recent_len)

    opp_d_run = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_run += 1
        i -= 1

    exp_run = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'C' and history[i][1] == 'D':
        exp_run += 1
        i -= 1

    dd_run = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'D':
        dd_run += 1
        i -= 1

    d_trans = 0
    forgiven = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            d_trans += 1
            if history[i][1] == 'C':
                forgiven += 1

    exploit_forgive = False
    if n > 10 and d_trans > 0 and forgiven >= 1 and forgiven * 2 >= d_trans and recent_opp_coop >= 0.6 and opp_c * 2 >= n:
        exploit_forgive = True

    perfect_forgive = False
    if d_trans >= 3 and forgiven == d_trans and recent_opp_coop >= 0.8 and opp_c * 2 >= n:
        perfect_forgive = True

    if n >= 96:
        if last_opp == 'C' and opp_c * 3 >= n * 2 and recent_opp_coop >= 0.8 and opp_d_run == 0:
            if perfect_forgive:
                return 'D'
            return 'C'
        if last_opp == 'D' or opp_d_run >= 3 or opp_d * 3 >= n * 2:
            return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if opp_d == n and opp_d_run >= 2:
                return 'D'
            if opp_d_run >= 5:
                return 'D'
            if opp_d * 2 >= n + 5 and recent_opp_coop < 0.4:
                return 'D'
            if exp_run >= 5 and recent_opp_c == 0:
                return 'D'
            return 'C'
        else:
            if opp_d == n:
                return 'D'
            if opp_d_run >= 8 and recent_opp_c == 0:
                return 'D'
            if dd_run == 1 and n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                if recent_opp_c >= 1 and opp_c * 2 >= n:
                    return 'C'
                return 'D'
            if dd_run >= 3 and recent_opp_c >= 1 and opp_c * 3 >= n:
                return 'C'
            if dd_run >= 5 and opp_c * 2 >= n and rng.random() < 0.08:
                return 'C'
            return 'D'

    if exploit_forgive:
        return 'D'

    if n >= 3 and history[-2][1] == 'D':
        run = 0
        unprov = 0
        i = n - 2
        while i >= 0 and history[i][1] == 'D':
            run += 1
            if history[i][0] == 'C':
                unprov += 1
            i -= 1
        if 2 <= run <= 4 and unprov >= run - 1 and opp_c > 0:
            return 'D'

    return 'C'
